  note "  SUPABASE_SERVICE_ROLE_KEY from it."
  confirm "Continue anyway, checking everything by eye?" || exit 1
else
  note "OK: $ENV_FILE found."
fi

command -v curl >/dev/null 2>&1 || warn "curl not found: the automatic checks will be skipped."
printf '\n'
pause "Ready?"

# -- 2 ---------------------------------------------------------------------
stage "Paystack: set the Test Webhook URL"
say "This is ticket 28, and the whole reason the last payment vanished."
printf '\n'
open_url "https://dashboard.paystack.com/#/settings/developers"
