  warn "Stopping here. Nothing below works until this field is set."
  exit 1
fi

# -- 3 ---------------------------------------------------------------------
stage "Wake Render"
say "Paystack's test-mode retries time out after 30 seconds. Render's measured"
say "cold start is over 45. A webhook arriving at a sleeping instance is lost,"
say "and the hourly retry finds it asleep again."
printf '\n'
warn "This is a stage 10 blocker, not a courtesy."
printf '\n'
if command -v curl >/dev/null 2>&1; then
  say "Waking it now, and timing the response..."
  printf '\n'
  _started=$(date +%s)
  if curl -fsS -o /dev/null --max-time 120 "$RENDER_HOST/api/mobile/config"; then
    _elapsed=$(( $(date +%s) - _started ))
    printf '  %sOK: Render answered in %ss%s\n' "$GREEN" "$_elapsed" "$RESET"
    if (( _elapsed > 20 )); then
      printf '\n'
      warn "That was a cold start. Call it once more before the checkout so the"
      note "  instance is warm when Paystack knocks."
    fi
  else
    warn "Render did not answer. Open its dashboard and check the service is live."
    open_url "https://dashboard.render.com"
    pause "Press Enter once Render is answering."
  fi
else
  open_url "$RENDER_HOST/api/mobile/config"
  step "Confirm it returns JSON, not an error page."
  pause
fi
printf '\n'
note "Keep this instance warm for the next three stages."
pause

# -- 4 ---------------------------------------------------------------------
